"""Declarative base of the V3 database models and the id generator the design asks for."""

from __future__ import annotations

import os
import time
import uuid

from sqlalchemy import MetaData
from sqlalchemy.orm import DeclarativeBase


class Base(DeclarativeBase):
    """All V3 tables. Their own MetaData keeps them apart from the legacy ORM's tables."""

    metadata = MetaData()


def uuid7() -> uuid.UUID:
    """A UUIDv7 (RFC 9562): ids are generated by the application and ordered by time (D1 item 5).

    Python 3.11 has no uuid.uuid7; this is the RFC layout: 48-bit Unix milliseconds, version 7,
    74 random bits, variant 10.
    """
    ms = time.time_ns() // 1_000_000
    rand = int.from_bytes(os.urandom(10), "big")
    value = (ms & 0xFFFF_FFFF_FFFF) << 80
    value |= 0x7 << 76
    value |= ((rand >> 62) & 0xFFF) << 64
    value |= 0b10 << 62
    value |= rand & 0x3FFF_FFFF_FFFF_FFFF
    return uuid.UUID(int=value)
